"use client"

import {
  forwardRef,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type AnimationEvent,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react"

import { getPulseDriverConfig, registerPulseInstance } from "./pulse-driver"
import {
  startBeamColorRenderer,
  type BeamColorRendererHandle,
  type BeamColorRendererOptions,
} from "./beam-color-renderer"
import "./border-beam.css"

export type BorderBeamSize = "sm" | "md" | "line" | "pulse-inner" | "pulse-outside"
export type BorderBeamTheme = "dark" | "light" | "auto"
export type BorderBeamColorVariant = "colorful" | "mono" | "ocean" | "sunset"

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect

export interface BorderBeamProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  children: ReactNode
  size?: BorderBeamSize
  colorVariant?: BorderBeamColorVariant
  theme?: BorderBeamTheme
  active?: boolean
  borderRadius?: number
  staticColors?: boolean
  duration?: number
  strength?: number
  brightness?: number
  saturation?: number
  hueRange?: number
  onActivate?: () => void
  onDeactivate?: () => void
}

const SIZE_DEFAULT_RADIUS: Record<BorderBeamSize, number> = {
  sm: 32,
  md: 16,
  line: 16,
  "pulse-inner": 16,
  "pulse-outside": 16,
}

function useSystemTheme(enabled: boolean): "dark" | "light" {
  const [sysTheme, setSysTheme] = useState<"dark" | "light">(() => {
    if (typeof window === "undefined") return "dark"
    return window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light"
  })

  useEffect(() => {
    if (!enabled) return
    const mq = window.matchMedia("(prefers-color-scheme: dark)")
    const handler = (e: MediaQueryListEvent) =>
      setSysTheme(e.matches ? "dark" : "light")
    mq.addEventListener("change", handler)
    return () => mq.removeEventListener("change", handler)
  }, [enabled])

  return sysTheme
}

export const BorderBeam = forwardRef<HTMLDivElement, BorderBeamProps>(
  function BorderBeam(
    {
      children,
      size = "md",
      colorVariant = "colorful",
      theme,
      active = true,
      borderRadius,
      staticColors = false,
      duration,
      strength = 1,
      brightness,
      saturation,
      hueRange = 30,
      className,
      style,
      onActivate,
      onDeactivate,
      onAnimationEnd: consumerOnAnimationEnd,
      ...rest
    },
    forwardedRef
  ) {
    const internalRef = useRef<HTMLDivElement | null>(null)
    const [phase, setPhase] = useState<"idle" | "active" | "fading">(
      active ? "active" : "idle"
    )
    const [prevActive, setPrevActive] = useState(active)
    // Adjust state during render when the `active` prop changes, instead of
    // calling setState from an effect (avoids the extra render pass).
    if (active !== prevActive) {
      setPrevActive(active)
      setPhase(active ? "active" : "fading")
    }
    const [detectedRadius, setDetectedRadius] = useState<number | null>(null)
    const [isVisible, setIsVisible] = useState(true)
    const isVisibleRef = useRef(true)
    const [pulseGlowScale, setPulseGlowScale] = useState({ x: 1, y: 1 })
    const colorCanvasRefs = useRef<Array<HTMLCanvasElement | null>>([])
    const rendererHandleRef = useRef<BeamColorRendererHandle | null>(null)
    const rendererOptionsRef = useRef<Omit<BeamColorRendererOptions, "root"> | null>(null)
    const [gpuColorsActive, setGpuColorsActive] = useState(false)
    const [gpuColorsFallback, setGpuColorsFallback] = useState(false)

    const isPulse = size === "pulse-inner" || size === "pulse-outside"

    const systemTheme = useSystemTheme(theme === "auto")
    const resolvedTheme = theme === "auto" ? systemTheme : (theme ?? "dark")

    useEffect(() => {
      isVisibleRef.current = isVisible
    }, [isVisible])

    useIsomorphicLayoutEffect(() => {
      if (borderRadius != null) return
      const child = internalRef.current?.firstElementChild as HTMLElement | null
      if (!child) return
      const r = parseFloat(getComputedStyle(child).borderTopLeftRadius)
      if (!Number.isNaN(r) && r > 0) setDetectedRadius(r)
    }, [borderRadius, children])

    // Pause the (paint-heavy) pulse animations while the element is scrolled
    // offscreen. This stops per-frame painting entirely for hidden instances
    // without changing their logical active/fading state.
    useEffect(() => {
      const el = internalRef.current
      if (!el || typeof IntersectionObserver === "undefined") return

      const observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) setIsVisible(entry.isIntersecting)
        },
        // Start animating slightly before the element scrolls into view.
        { rootMargin: "256px" }
      )

      observer.observe(el)
      return () => observer.disconnect()
    }, [])

    // Pulse-outside glow geometry is authored in fixed pixels for a reference
    // element (~350x140). Measure the wrapped element and scale the glow
    // per-axis so the halo grows/shrinks to fit any component it's applied to.
    useEffect(() => {
      if (size !== "pulse-outside") return

      const el = internalRef.current
      if (!el) return

      const REF_WIDTH = 350
      const REF_HEIGHT = 140
      // Allow the glow to both shrink (small buttons) and grow (large cards),
      // with generous bounds to avoid degenerate geometry at the extremes.
      const MIN_SCALE = 0.35
      const MAX_SCALE = 4
      const clamp = (value: number) =>
        Math.max(MIN_SCALE, Math.min(MAX_SCALE, value))

      const measure = () => {
        const child = el.firstElementChild as HTMLElement | null
        if (!child) return
        const rect = child.getBoundingClientRect()
        if (!rect.width || !rect.height) return
        const x = +clamp(rect.width / REF_WIDTH).toFixed(3)
        const y = +clamp(rect.height / REF_HEIGHT).toFixed(3)
        setPulseGlowScale((prev) =>
          prev.x === x && prev.y === y ? prev : { x, y }
        )
      }

      measure()
      if (typeof ResizeObserver === "undefined") return

      const child = el.firstElementChild as HTMLElement | null
      if (!child) return

      const resizeObserver = new ResizeObserver(measure)
      resizeObserver.observe(child)
      return () => resizeObserver.disconnect()
    }, [size, children])

    const handleAnimationEnd = useCallback(
      (e: AnimationEvent<HTMLDivElement>) => {
        if (e.target !== e.currentTarget) {
          consumerOnAnimationEnd?.(e)
          return
        }
        const name = e.animationName
        if (name.includes("fade-out")) {
          setPhase("idle")
          onDeactivate?.()
        } else if (name.includes("fade-in")) {
          onActivate?.()
        }
        consumerOnAnimationEnd?.(e)
      },
      [onActivate, onDeactivate, consumerOnAnimationEnd]
    )

    const setRefs = useCallback(
      (node: HTMLDivElement | null) => {
        internalRef.current = node
        if (typeof forwardedRef === "function") forwardedRef(node)
        else if (forwardedRef) forwardedRef.current = node
      },
      [forwardedRef]
    )

    const finalRadius =
      borderRadius ?? detectedRadius ?? SIZE_DEFAULT_RADIUS[size]
    const finalStaticColors = colorVariant === "mono" || staticColors
    const clampedStrength = Math.max(0, Math.min(1, strength))
    const finalDuration = duration ?? (size === "line" ? 3.1 : isPulse ? 2.3 : 1.96)
    const finalHueRange = size === "line" ? Math.min(hueRange, 13) : hueRange
    const useGpuColors = true
    const rendererOptions = useMemo<Omit<BeamColorRendererOptions, "root">>(
      () => ({
        variant: colorVariant,
        hueRange: finalHueRange,
        brightness: brightness ?? 1.3,
        saturation:
          saturation ??
          (size === "sm"
            ? resolvedTheme === "dark"
              ? 1.2
              : 1.8
            : resolvedTheme === "dark"
              ? 1.2
              : size === "line"
                ? 1.95
                : 1.5),
        duration: finalDuration,
        size,
        theme: resolvedTheme,
        staticColors: finalStaticColors,
        pulseGlowScale,
        reducedMotion:
          typeof window !== "undefined" &&
          window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
            ? true
            : false,
      }),
      [
        brightness,
        colorVariant,
        finalDuration,
        finalHueRange,
        finalStaticColors,
        pulseGlowScale,
        resolvedTheme,
        saturation,
        size,
      ]
    )
    const rendererEnabled = phase === "active" || phase === "fading"

    useEffect(() => {
      rendererOptionsRef.current = rendererOptions
    }, [rendererOptions])

    useEffect(() => {
      if (!useGpuColors || !rendererEnabled || rendererOptions.reducedMotion) {
        return
      }

      const canvases = colorCanvasRefs.current.filter(
        (canvas): canvas is HTMLCanvasElement => canvas != null
      )
      const root = internalRef.current
      if (canvases.length !== 3 || !root) return

      let cancelled = false
      const renderer = startBeamColorRenderer(canvases, {
        ...rendererOptionsRef.current!,
        root,
      })

      void renderer.then(
        (handle) => {
          if (cancelled) {
            handle.dispose()
            return
          }
          rendererHandleRef.current = handle
          handle.setVisible(isVisibleRef.current)
          setGpuColorsFallback(false)
          setGpuColorsActive(true)
        },
        () => {
          if (!cancelled) {
            setGpuColorsActive(false)
            setGpuColorsFallback(true)
          }
        }
      )

      return () => {
        cancelled = true
        setGpuColorsActive(false)
        setGpuColorsFallback(false)
        const handle = rendererHandleRef.current
        rendererHandleRef.current = null
        handle?.dispose()
        void renderer.then((pendingHandle) => {
          if (pendingHandle !== handle) pendingHandle.dispose()
        }, () => undefined)
      }
    }, [rendererEnabled, rendererOptions.reducedMotion, useGpuColors])

    useEffect(() => {
      const root = internalRef.current
      if (root) {
        rendererHandleRef.current?.update({ ...rendererOptions, root })
      }
    }, [rendererOptions])

    useEffect(() => {
      rendererHandleRef.current?.setVisible(isVisible)
    }, [isVisible])

    // Detune breath/spike against the travel period to avoid visible resonance.
    const breatheDuration = finalDuration * 1.3
    const spikeDuration = finalDuration * 1.33
    const spike2Duration = finalDuration * 1.7

    // Runtime config for the JS breathing driver (null for non-pulse sizes).
    const driverConfig = useMemo(
      () =>
        isPulse
          ? getPulseDriverConfig(
              size,
              resolvedTheme,
              finalDuration,
              finalStaticColors
            )
          : null,
      [isPulse, size, resolvedTheme, finalDuration, finalStaticColors]
    )

    // Drive the pulse breathing from the shared, fps-capped rAF loop while the
    // instance is on, onscreen, and the user hasn't requested reduced motion.
    useEffect(() => {
      if (!driverConfig || gpuColorsActive) return
      if (!(phase === "active" || phase === "fading") || !isVisible) return

      const el = internalRef.current
      if (!el) return

      if (
        typeof window !== "undefined" &&
        window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
      ) {
        return
      }

      return registerPulseInstance(el, driverConfig)
    }, [driverConfig, gpuColorsActive, phase, isVisible])

    const beamStyle: CSSProperties = {
      ...style,
      ["--beam-radius" as string]: `${finalRadius}px`,
      ["--beam-inner-radius" as string]: `${Math.max(0, finalRadius - 1)}px`,
      ["--beam-duration" as string]: `${finalDuration}s`,
      ["--beam-strength" as string]: clampedStrength,
      ...(brightness != null
        ? { ["--beam-brightness" as string]: brightness }
        : {}),
      ["--beam-hue-range" as string]: `${finalHueRange}deg`,
      ...(saturation != null
        ? { ["--beam-saturation" as string]: saturation }
        : {}),
      ...(size === "line"
        ? {
            ["--beam-breathe-duration" as string]: `${breatheDuration.toFixed(2)}s`,
            ["--beam-spike-duration" as string]: `${spikeDuration.toFixed(2)}s`,
            ["--beam-spike2-duration" as string]: `${spike2Duration.toFixed(2)}s`,
          }
        : {}),
      ...(size === "pulse-outside"
        ? {
            ["--pulse-glow-sx" as string]: pulseGlowScale.x,
            ["--pulse-glow-sy" as string]: pulseGlowScale.y,
          }
        : {}),
    }

    return (
      <div
        {...rest}
        ref={setRefs}
        className={className}
        style={beamStyle}
        data-beam=""
        data-size={size}
        data-variant={colorVariant}
        data-theme={theme != null ? resolvedTheme : undefined}
        data-static-colors={finalStaticColors ? "" : undefined}
        data-vgpu-colors={gpuColorsActive ? "" : undefined}
        data-vgpu-fallback={gpuColorsFallback ? "" : undefined}
        data-vgpu-paused={useGpuColors && !isVisible ? "" : undefined}
        data-active={phase === "active" ? "" : undefined}
        data-fading={phase === "fading" ? "" : undefined}
        data-paused={
          isPulse && (phase === "active" || phase === "fading") && !isVisible
            ? ""
            : undefined
        }
        onAnimationEnd={handleAnimationEnd}
      >
        {children}
        {useGpuColors
          ? (["stroke", "inner", "bloom"] as const).map((layer, index) => (
              <canvas
                key={layer}
                ref={(canvas) => {
                  colorCanvasRefs.current[index] = canvas
                }}
                aria-hidden="true"
                data-beam-color-layer={layer}
              />
            ))
          : null}
        <div data-beam-bloom />
      </div>
    )
  }
)

BorderBeam.displayName = "BorderBeam"

import { clock, effect, frame, frameLoop, init, surface } from "vgpu"
import beamColorShader from "./beam-color.wgsl"

import type { BorderBeamColorVariant, BorderBeamSize } from "./border-beam"

export type BeamColorLayer = "stroke" | "inner" | "bloom"

export interface BeamColorRendererHandle {
  update(options: BeamColorRendererOptions): void
  setVisible(visible: boolean): void
  dispose(): void
}

export interface BeamColorRendererOptions {
  variant: BorderBeamColorVariant
  size: BorderBeamSize
  theme: "dark" | "light"
  hueRange: number
  brightness: number
  saturation: number
  duration: number
  staticColors: boolean
  pulseGlowScale: { x: number; y: number }
  root: HTMLElement
  reducedMotion: boolean
}

type Gpu = Awaited<ReturnType<typeof init>>
type BeamSurface = ReturnType<typeof surface>
type BeamEffect = ReturnType<typeof effect>

type LayerEntry = {
  canvas: HTMLCanvasElement
  surface: BeamSurface
  effect: BeamEffect
  layer: BeamColorLayer
  unsubscribeResize: () => void
}

type ManagedEntry = {
  canvases: HTMLCanvasElement[]
  layers: LayerEntry[]
  root: HTMLElement
  options: BeamColorRendererOptions
  leases: number
  animated: boolean
  visible: boolean
  rootObserver?: ResizeObserver
  update(options: BeamColorRendererOptions): void
  disposeUnderlying(): void
}

const LAYERS: BeamColorLayer[] = ["stroke", "inner", "bloom"]
const MODE: Record<BorderBeamSize, number> = {
  sm: 1,
  md: 0,
  line: 2,
  "pulse-inner": 3,
  "pulse-outside": 4,
}
const VARIANT: Record<BorderBeamColorVariant, number> = {
  colorful: 0,
  mono: 1,
  ocean: 2,
  sunset: 3,
}

let gpuPromise: Promise<Gpu> | null = null
let sharedGpu: Gpu | null = null
let sharedLoop: ReturnType<typeof frameLoop> | null = null
let pendingRendererStarts = 0
const managedEntries = new Set<ManagedEntry>()
const animatedEntries = new Set<ManagedEntry>()
const canvasEntries = new WeakMap<HTMLCanvasElement, ManagedEntry>()

function getSharedGpu(): Promise<Gpu> {
  if (!gpuPromise) {
    gpuPromise = init().then(
      (gpu) => {
        sharedGpu = gpu
        return gpu
      },
      (error) => {
        gpuPromise = null
        throw error
      }
    )
  }
  return gpuPromise
}

function stopSharedGpuIfUnused(gpu: Gpu): void {
  if (
    managedEntries.size > 0 ||
    pendingRendererStarts > 0 ||
    sharedGpu !== gpu
  ) return
  sharedLoop?.stop()
  sharedLoop = null
  sharedGpu = null
  gpuPromise = null
  gpu.dispose()
}

function colorIndex(variant: BorderBeamColorVariant): number {
  return VARIANT[variant]
}

function setEffectParams(
  entry: ManagedEntry,
  layer: LayerEntry,
  time: number
): void {
  const rootRect = entry.root.getBoundingClientRect()
  const canvasRect = layer.canvas.getBoundingClientRect()
  const canvasWidth = Math.max(layer.surface.size[0], 1)
  const canvasClientWidth = Math.max(layer.canvas.clientWidth, 1)
  const dpr = canvasWidth / canvasClientWidth
  const rootWidth = Math.max(rootRect.width * dpr, canvasWidth)
  const rootHeight = Math.max(rootRect.height * dpr, layer.surface.size[1])

  layer.effect.set({
    params: {
      time,
      variant: colorIndex(entry.options.variant),
      hueRange: entry.options.hueRange,
      brightness: entry.options.brightness,
      saturation: entry.options.saturation,
      mode: MODE[entry.options.size],
      dark: entry.options.theme === "dark" ? 1 : 0,
      width: layer.surface.size[0],
      height: layer.surface.size[1],
      rootWidth,
      rootHeight,
      duration: Math.max(entry.options.duration, 0.001),
      staticColors: entry.options.staticColors ? 1 : 0,
      pulseScaleX: entry.options.pulseGlowScale.x,
      pulseScaleY: entry.options.pulseGlowScale.y,
      offsetX: (canvasRect.left - rootRect.left) * dpr,
      offsetY: (canvasRect.top - rootRect.top) * dpr,
      layer: LAYERS.indexOf(layer.layer),
    },
  })
}

function renderStatic(gpu: Gpu, entry: ManagedEntry): void {
  frame(gpu, (currentFrame) => {
    for (const layer of entry.layers) {
      setEffectParams(entry, layer, 0)
      currentFrame.pass(
        { target: layer.surface, clear: [0, 0, 0, 0] },
        layer.effect
      )
    }
  })
}

function ensureSharedLoop(gpu: Gpu): void {
  if (sharedLoop || animatedEntries.size === 0) return
  const time = clock(gpu)
  sharedLoop = frameLoop(gpu, (currentFrame) => {
    animatedEntries.forEach((entry) => {
      entry.layers.forEach((layer) => {
        setEffectParams(entry, layer, time.time)
        currentFrame.pass(
          { target: layer.surface, clear: [0, 0, 0, 0] },
          layer.effect
        )
      })
    })
  }, { fps: 30 })
}

function updateAnimationMembership(
  gpu: Gpu,
  entry: ManagedEntry,
  animated: boolean
): void {
  entry.animated = animated
  if (animated && entry.visible) {
    animatedEntries.add(entry)
    ensureSharedLoop(gpu)
    return
  }

  animatedEntries.delete(entry)
  renderStatic(gpu, entry)
  if (animatedEntries.size === 0) {
    sharedLoop?.stop()
    sharedLoop = null
  }
}

function createLease(
  canvases: HTMLCanvasElement[],
  entry: ManagedEntry,
  gpu: Gpu
): BeamColorRendererHandle {
  entry.leases += 1
  let disposed = false
  return {
    update(options) {
      if (disposed) return
      entry.update(options)
    },
    setVisible(visible) {
      if (disposed || entry.visible === visible) return
      entry.visible = visible
      updateAnimationMembership(gpu, entry, entry.animated)
    },
    dispose() {
      if (disposed) return
      disposed = true
      entry.leases -= 1
      if (entry.leases > 0) return

      managedEntries.delete(entry)
      animatedEntries.delete(entry)
      entry.rootObserver?.disconnect()
      entry.layers.forEach((layer) => {
        layer.unsubscribeResize()
        layer.surface.dispose()
      })
      canvases.forEach((canvas) => canvasEntries.delete(canvas))
      if (animatedEntries.size === 0) {
        sharedLoop?.stop()
        sharedLoop = null
      }
      if (sharedGpu) stopSharedGpuIfUnused(sharedGpu)
    },
  }
}

function installGeometryObservers(gpu: Gpu, entry: ManagedEntry): void {
  const update = () => {
    entry.layers.forEach((layer) => setEffectParams(entry, layer, 0))
    if (!entry.animated) renderStatic(gpu, entry)
  }

  if (typeof ResizeObserver !== "undefined") {
    entry.rootObserver = new ResizeObserver(update)
    entry.rootObserver.observe(entry.root)
  }
}

export async function startBeamColorRenderer(
  canvases: HTMLCanvasElement[],
  options: BeamColorRendererOptions
): Promise<BeamColorRendererHandle> {
  const existingBeforeInit = canvasEntries.get(canvases[0])
  if (existingBeforeInit) {
    existingBeforeInit.update(options)
    return createLease(canvases, existingBeforeInit, sharedGpu!)
  }

  pendingRendererStarts += 1
  let pending = true
  const finishPending = () => {
    if (!pending) return
    pending = false
    pendingRendererStarts -= 1
  }

  let gpu: Gpu
  try {
    gpu = await getSharedGpu()
    const existing = canvasEntries.get(canvases[0])
    if (existing) {
      existing.update(options)
      finishPending()
      return createLease(canvases, existing, gpu)
    }
  } catch (error) {
    finishPending()
    throw error
  }

  const layers: LayerEntry[] = []
  try {
    for (let index = 0; index < LAYERS.length; index += 1) {
      const canvas = canvases[index]
      const output = surface(gpu, canvas, {
        alphaMode: "premultiplied",
        clearColor: [0, 0, 0, 0],
        dpr: [1, 2],
        label: `border-beam-${LAYERS[index]}`,
      })
      const color = effect(gpu, beamColorShader, {
        blend: "premultiplied",
        label: `border-beam-${LAYERS[index]}`,
        set: {
          params: {
            time: 0,
            variant: colorIndex(options.variant),
            hueRange: options.hueRange,
            brightness: options.brightness,
            saturation: options.saturation,
            mode: MODE[options.size],
            dark: options.theme === "dark" ? 1 : 0,
            width: output.size[0],
            height: output.size[1],
            rootWidth: output.size[0],
            rootHeight: output.size[1],
            duration: Math.max(options.duration, 0.001),
            staticColors: options.staticColors ? 1 : 0,
            pulseScaleX: options.pulseGlowScale.x,
            pulseScaleY: options.pulseGlowScale.y,
            offsetX: 0,
            offsetY: 0,
            layer: index,
          },
        },
      })
      const layer: LayerEntry = {
        canvas,
        surface: output,
        effect: color,
        layer: LAYERS[index],
        unsubscribeResize: () => undefined,
      }
      layers.push(layer)
    }

    const entry: ManagedEntry = {
      canvases,
      layers,
      root: options.root,
      options,
      leases: 0,
      animated: false,
      visible: true,
      update(nextOptions: BeamColorRendererOptions) {
        entry.options = nextOptions
        layers.forEach((layer) => setEffectParams(entry, layer, 0))
        updateAnimationMembership(gpu, entry, shouldAnimate(nextOptions))
      },
      disposeUnderlying() {
        animatedEntries.delete(entry)
        managedEntries.delete(entry)
        entry.rootObserver?.disconnect()
        layers.forEach((layer) => {
          layer.unsubscribeResize()
          layer.surface.dispose()
        })
        stopSharedGpuIfUnused(gpu)
      },
    }

    layers.forEach((layer) => {
      layer.unsubscribeResize = layer.surface.onResize(() => {
        setEffectParams(entry, layer, 0)
      })
    })
    managedEntries.add(entry)
    canvases.forEach((canvas) => canvasEntries.set(canvas, entry))
    installGeometryObservers(gpu, entry)
    updateAnimationMembership(gpu, entry, shouldAnimate(options))
    finishPending()
    return createLease(canvases, entry, gpu)
  } catch (error) {
    finishPending()
    layers.forEach((layer) => {
      layer.unsubscribeResize()
      layer.surface.dispose()
    })
    stopSharedGpuIfUnused(gpu)
    throw error
  }
}

function shouldAnimate(options: BeamColorRendererOptions): boolean {
  return !options.reducedMotion
}

/*
 * border-beam.css — auto-generated by scripts/generate-css.mjs
 *
 * Refactored from Jakubantalik/border-beam (MIT) into static, registry-native CSS.
 * All per-instance @property names eliminated; multi-instance independence is
 * provided by the CSS standard (each element holds its own value of each
 * inheriting custom property).
 *
 * Supports border (sm/md), line (bottom-only traveling glow), and pulse
 * (pulse-inner / pulse-outside breathing glow) size variants.
 * Theme can be set per-component via data-theme="dark"|"light" attribute,
 * or inherited from the page's .dark class (default when no data-theme is set).
 *
 * The pulse breathing (blob size/drift/quadrant-opacity + hue drift) is driven
